CREATE OR REPLACE VIEW GATEC_LAB.GIV_LAB_LANC_PARADA AS
SELECT LPA.ID_LANC_PARADA,        LPA.COD_EMPR,        EMP.DSC_EMPR,        LPA.SAF_ANO_SAFRA,        LPA.ID_SETOR_PARADA,        STP.STP_DESC,        LPA.ID_CLASSE_PARADA,        CLA.CLP_DESC,        LPA.ID_EQUIP_PARADA,        EQP.EQP_DESC,        LPA.ID_CAUSA_PARADA,        CAP.CAP_DESC,        LPA.LAN_DATA_HORA_INICIO,        LPA.LAN_DATA_HORA_FIM,        LPA.LAN_HORAS_PARADAS,        LPA.LAN_MOTIVO_OUTROS,        LPA.LAN_OBSERVACOES,        PSS.PNS_STATUS AS SETOR_ATIVO,        PCS.PNS_STATUS AS CLASSE_ATIVA,        PES.PNS_STATUS AS EQUIPAMENTO_ATIVO,        PCAS.PNS_STATUS AS CAUSA_ATIVA   FROM GI_LAB_LANC_PARADA LPA   JOIN GA_EMPR EMP ON (EMP.COD_EMPR = LPA.COD_EMPR)   JOIN GI_LAB_CLASSE_CAUSA_PARADA CCP     ON (CCP.ID_SETOR_PARADA = LPA.ID_SETOR_PARADA AND        CCP.ID_CLASSE_PARADA = LPA.ID_CLASSE_PARADA AND        CCP.ID_CAUSA_PARADA = LPA.ID_CAUSA_PARADA)   JOIN GI_LAB_CAUSA_PARADA CAP     ON (CAP.ID_CAUSA_PARADA = CCP.ID_CAUSA_PARADA)   JOIN GI_LAB_PARADA_CAUSA_STATUS PCAS     ON (CAP.ID_CAUSA_PARADA = PCAS.ID_CAUSA_PARADA AND        PCAS.COD_EMPR = EMP.COD_EMPR)   JOIN GI_LAB_EQUIP_PARADA EQP     ON (EQP.ID_SETOR_PARADA = LPA.ID_SETOR_PARADA AND         EQP.ID_CLASSE_PARADA = LPA.ID_CLASSE_PARADA AND         EQP.ID_EQUIP_PARADA = LPA.ID_EQUIP_PARADA)   JOIN GI_LAB_PARADA_EQUIP_STATUS PES     ON (EQP.ID_SETOR_PARADA = PES.ID_SETOR_PARADA AND        EQP.ID_CLASSE_PARADA = PES.ID_CLASSE_PARADA AND        EQP.ID_EQUIP_PARADA = PES.ID_EQUIP_PARADA AND        PES.COD_EMPR = EMP.COD_EMPR)   JOIN GI_LAB_CLASSE_PARADA CLA     ON (CLA.ID_SETOR_PARADA = EQP.ID_SETOR_PARADA AND        CLA.ID_CLASSE_PARADA = EQP.ID_CLASSE_PARADA)   JOIN GI_LAB_PARADA_CLASSE_STATUS PCS     ON (CLA.ID_SETOR_PARADA = PCS.ID_SETOR_PARADA AND        CLA.ID_CLASSE_PARADA = PCS.ID_CLASSE_PARADA AND        PCS.COD_EMPR = EMP.COD_EMPR)   JOIN GI_LAB_SETOR_PARADA STP     ON (STP.ID_SETOR_PARADA = CLA.ID_SETOR_PARADA)   JOIN GI_LAB_PARADA_SETOR_STATUS PSS     ON (STP.ID_SETOR_PARADA = PSS.ID_SETOR_PARADA AND        PSS.COD_EMPR = EMP.COD_EMPR)
 
/
